public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Returns information about a chat folder by its identifier
    /// </summary>
    public Task<TdLib.TdApi.Objects.ChatFolder> GetChatFolderAsync(int chatFolderId = default)
    {

           using var activity =  StartCallActivity("GetChatFolderAsync", typeof(GetChatFolder).FullName ?? "GetChatFolderAsync");

           try
           {
             return client.GetChatFolderAsync(chatFolderId);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
